var RenovationOffers=(()=>{
'use strict';
const number=v=>{const x=Number(v);return Number.isFinite(x)&&x>=0?x:0},round=x=>Math.round((x+Number.EPSILON)*100)/100;
function url(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
function quote(offer,need,waste=0){const size=number(offer.packSize);if(!size||!number(need))return null;const quantity=number(need)*(1+number(waste)/100),packs=Math.ceil(Number((quantity/size).toFixed(10))),goods=round(packs*number(offer.price)),shipping=number(offer.shipping);return {packs,quantity,delivered:packs*size,goods,total:round(goods+shipping),unitPrice:number(offer.price)/size,effective:round((goods+shipping)/number(need))}}
function apply(resource,offer,waste=0){const q=quote(offer,resource.qty,waste);if(!q)throw Error('Bitte zuerst eine benötigte Menge größer null festlegen.');if(offer.unit!==resource.unit)throw Error('Die Einheit des Angebots muss zur Beschaffungsposition passen.');return {...resource,unitPrice:q.total/number(resource.qty),supplier:offer.supplier,url:url(offer.url),selectedOffer:{...offer,selectedAt:new Date().toISOString(),...q,waste:number(waste)},offerWaste:number(waste)}}
let api,current,editing='';const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(x);
function summary(r){const o=r.selectedOffer;return o?`<p class="offer-selected"><strong>Ausgewähltes Angebot: ${esc(o.productTitle||o.supplier)}</strong> · ${money(o.total)} inkl. Versand<br><small>${o.packs} Packung(en) · Stand ${esc(new Date(o.selectedAt).toLocaleDateString('de-DE'))}. Planpreis enthält Versand und Packungsrundung; spätere Preisänderungen ändern diesen Angebotsstand nicht.</small></p>`:''}
function open(id){current=id;editing='';const r=api.getResource(id);if(!r)return;$('offer-heading').textContent='Angebote · '+r.label;$('offer-need').textContent=`Bedarf: ${r.qty} ${r.unit}. Alle Angebote in dieser Einheit erfassen (z. B. Packungsinhalt in m²).`;$('offer-waste').value=r.offerWaste||0;$('offer-unit').value=r.unit;$('offer-search').value=r.label;reset();render();$('offer-dialog').showModal()}
function reset(){editing='';$('offer-form').reset();$('offer-product').value='';$('offer-unit').value=api.getResource(current)?.unit||'';$('offer-pack').value=1;$('offer-shipping').value=0;$('offer-feedback').textContent=''}
function render(){const r=api.getResource(current);if(!r)return;const rows=(r.offers||[]).map(o=>({o,q:o.unit!==r.unit?null:quote(o,r.qty,$('offer-waste').value)})).sort((a,b)=>(a.q?.total??Infinity)-(b.q?.total??Infinity));$('offer-list').innerHTML=rows.map(({o,q},i)=>`<article class="offer-row"><div>${o.productTitle?`<h4>${esc(o.productTitle)}</h4>`:''}<strong>${esc(o.supplier)}${i===0&&q?' · Günstigstes hinterlegtes Angebot':''}</strong><p>${money(o.price)} / Packung (${o.packSize} ${esc(o.unit)}) · ${money(o.price/o.packSize)} / ${esc(o.unit)}</p><small>Versand: ${money(o.shipping)} · Erfasst: ${esc(new Date(o.updatedAt).toLocaleDateString('de-DE'))}</small>${q?`<p><strong>${money(q.total)} gesamt</strong> · ${q.packs} Packung(en), ${q.delivered.toLocaleString('de-DE')} ${esc(o.unit)} inkl. Verschnitt</p>`:'<p>Menge und Einheit unter „Bearbeiten“ prüfen; die Angebotseinheit muss zur Position passen.</p>'}</div><div class="card-actions">${url(o.url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(url(o.url))}">Zum Angebot ↗</a>`:''}<button type="button" data-offer-apply="${esc(o.id)}" ${q?'':'disabled'}>Übernehmen</button><button type="button" data-offer-edit="${esc(o.id)}">Bearbeiten</button><button type="button" data-offer-delete="${esc(o.id)}">Entfernen</button></div></article>`).join('')||'<p>Noch keine Angebote hinterlegt.</p>'}
function init(options){api=options;const dialog=document.createElement('dialog');dialog.id='offer-dialog';dialog.innerHTML=`<div class="toolbar"><h2 id="offer-heading">Angebote vergleichen</h2><button id="offer-close" type="button">Schließen</button></div><p id="offer-need"></p><div class="offer-search"><label>Produkt suchen<input id="offer-search" maxlength="300"></label><button id="offer-search-go" type="button">Produkte finden</button></div><p class="muted">„Produkte finden“ zeigt Online-Preisvorschläge. Übernimm einen Vorschlag zur Prüfung und ergänze Packungsinhalt und Versand. Gespeicherte Angebote bleiben als Preisstand in diesem Browser; keine automatische Preisaktualisierung.</p><label>Verschnitt / Mehrbedarf (%)<input id="offer-waste" type="number" min="0" max="100" step="0.1" value="0"></label><p class="muted">Gilt nur für die Mengenberechnung dieses Vergleichs, keine zusätzliche Budgetreserve. Versand wird pro Angebot einmal gerechnet. Brutto-Endpreise verwenden; nur gleichwertige Produkte vergleichen.</p><div id="offer-list"></div><h3 id="offer-editor-title">Angebot hinzufügen / bearbeiten</h3><form id="offer-form"><div class="fields"><label>Produktbezeichnung · optional<input id="offer-product" maxlength="300"></label><label>Händler<input id="offer-supplier" required maxlength="200"></label><label>Produktlink<input id="offer-url" type="url" maxlength="2000" placeholder="https://…"></label><label>Bruttopreis pro Packung / Stück (€)<input id="offer-price" type="number" required min="0" max="100000000" step="0.01"></label><label>Inhalt je Packung / Stück<input id="offer-pack" type="number" required min="0.001" max="1000000" step="0.001" value="1"></label><label>Einheit (wie Position)<input id="offer-unit" readonly></label><label>Versand gesamt (€)<input id="offer-shipping" type="number" required min="0" max="1000000" step="0.01" value="0"></label></div><div class="dialog-actions"><button type="submit" class="btn">Angebot speichern</button><button type="button" id="offer-reset">Neues Angebot</button></div></form><p id="offer-feedback" role="status" aria-live="polite"></p><p class="muted">„Übernehmen“ ersetzt Preis und Anbieter der Beschaffungsposition, ohne Bestellung auszulösen. Rechnungen und Zahlungsstatus bleiben unverändert. Plan anschließend speichern.</p>`;document.body.appendChild(dialog);
$('offer-close').onclick=()=>dialog.close();$('offer-reset').onclick=reset;$('offer-waste').oninput=()=>{if($('offer-waste').checkValidity())render()};$('offer-search-go').onclick=()=>{const resourceId=current;RenovationShopping.open({query:$('offer-search').value,onChoose:item=>{if(current!==resourceId)return;reset();$('offer-product').value=item.title;$('offer-supplier').value=item.supplier;$('offer-url').value=item.url;$('offer-price').value=item.price;$('offer-pack').value='';$('offer-shipping').value=item.shipping??'';$('offer-feedback').textContent='Preisvorschlag: '+item.title+'. Bitte Inhalt pro Packung in '+$('offer-unit').value+' und Versandkosten bestätigen, dann Angebot speichern.';$('offer-pack').focus()}})};
$('offer-form').onsubmit=e=>{e.preventDefault();if(!$('offer-form').reportValidity())return;const link=$('offer-url').value.trim();if(link&&!url(link)){$('offer-feedback').textContent='Bitte einen gültigen http- oder https-Link ohne Zugangsdaten eingeben.';return}const r=api.getResource(current);if(!r)return;const o={id:editing||crypto.randomUUID(),supplier:$('offer-supplier').value.trim(),productTitle:$('offer-product').value.trim(),url:url(link),price:number($('offer-price').value),packSize:number($('offer-pack').value),shipping:number($('offer-shipping').value),unit:r.unit,updatedAt:new Date().toISOString()};if(!o.supplier)return;r.offers=(r.offers||[]).filter(x=>x.id!==o.id).concat(o);api.changed();reset();render()};
$('offer-list').onclick=e=>{const b=e.target.closest('button');if(!b)return;const r=api.getResource(current);if(!r)return;const id=b.dataset.offerApply||b.dataset.offerEdit||b.dataset.offerDelete,o=(r.offers||[]).find(x=>x.id===id);if(!o)return;if(b.dataset.offerEdit){editing=id;for(const [key,field]of Object.entries({productTitle:'product',supplier:'supplier',url:'url',price:'price',packSize:'pack',shipping:'shipping'}))$('offer-'+field).value=o[key]??'';$('offer-supplier').focus()}else if(b.dataset.offerDelete){if(!confirm('Dieses Angebot entfernen? Ein bereits übernommener Planpreis bleibt erhalten.'))return;r.offers=r.offers.filter(x=>x.id!==id);api.changed();reset();render()}else{if(!$('offer-waste').reportValidity())return;try{const next=apply(r,o,$('offer-waste').value);if(!confirm(`Angebot für ${money(next.selectedOffer.total)} übernehmen? Der bisherige Planpreis wird ersetzt. Die Einstellung zur Budgetanrechnung bleibt erhalten.`))return;Object.assign(r,next);api.changed();api.render();$('offer-feedback').textContent='Angebot übernommen. Bitte den Renovierungsplan speichern.'}catch(err){$('offer-feedback').textContent=err.message}}};
}
return {quote,apply,url,init,open,summary};})();
if(typeof module!=='undefined')module.exports=RenovationOffers;
